-- Signatures v3: start the ceremony schema over, much simpler than v2.
-- `signatures` now only tracks: the row id, its lifecycle `stage`, the S3
-- key of the document to sign, and where the signature goes on it.
-- Everything v2 had beyond that (signer identity, evidence keys, OTP,
-- consent, callback bookkeeping, cert tracking) is gone -- it gets
-- rebuilt incrementally, stage by stage, as this refactor progresses.
--
-- `doc_s3_key` is a UUIDv7 filename (time-ordered), generated by
-- `create_signature`, not the row's own `id`.
--
-- This is a DESTRUCTIVE migration: all existing rows in `signatures` are
-- dropped (dev only). The `down` direction restores the v2 shape
-- (structure only; data is not recovered).
--
-- Paired changes: libs/orm/signatures.py, services/signatures/src/handlers/
-- create_signature (new). The old 11 handlers + the `sign` worker move to
-- services/signatures/_legacy/ -- kept as reference, no longer deployed.

-- +migrate up

DROP INDEX IF EXISTS signatures_signer_email_idx;
DROP INDEX IF EXISTS signatures_expires_idx;
DROP TABLE IF EXISTS signatures;

CREATE TABLE signatures (
    id            UUID          PRIMARY KEY DEFAULT gen_random_uuid(),
    stage         VARCHAR(20)   NOT NULL DEFAULT 'FORM',
    doc_s3_key    TEXT          NOT NULL UNIQUE,
    sign_location JSONB
);

-- +migrate down

DROP TABLE IF EXISTS signatures;

-- Best-effort restore of the v2 shape so a manual rollback leaves a
-- working table for the old handler code (now under _legacy/). Data is
-- not recovered (dropped rows are gone).
CREATE TABLE signatures (
    sign_id                    VARCHAR(64)   PRIMARY KEY,
    signer_email               VARCHAR(320)  NOT NULL,
    signer_name                VARCHAR(200),
    signature_location         JSONB         NOT NULL,
    callback_url               TEXT,
    service_caller              VARCHAR(100),
    hash_original               VARCHAR(64)   NOT NULL,
    hash_signed                 VARCHAR(64),
    cert_serial                 VARCHAR(64),
    stage                       VARCHAR(20)   NOT NULL DEFAULT 'created',
    cedula_front_key            TEXT,
    cedula_back_key             TEXT,
    face_key                    TEXT,
    signature_key               TEXT,
    cedula_front_validated_at   TIMESTAMPTZ,
    cedula_back_validated_at    TIMESTAMPTZ,
    face_validated_at           TIMESTAMPTZ,
    consent_given_at            TIMESTAMPTZ,
    consent_terms_version       VARCHAR(50),
    otp_hash                    VARCHAR(64),
    otp_expires_at              TIMESTAMPTZ,
    otp_attempts                INT           NOT NULL DEFAULT 0,
    signed_at                   TIMESTAMPTZ,
    created_at                  TIMESTAMPTZ   NOT NULL DEFAULT NOW(),
    updated_at                  TIMESTAMPTZ   NOT NULL DEFAULT NOW(),
    expires_at                  TIMESTAMPTZ   NOT NULL,
    callback_sent_at            TIMESTAMPTZ,
    callback_failed_at          TIMESTAMPTZ,
    callback_error              TEXT,
    CONSTRAINT signatures_stage_check
        CHECK (stage IN (
            'created', 'identity', 'consent', 'otp', 'signing',
            'signed', 'expired', 'failed'
        ))
);

CREATE INDEX signatures_expires_idx ON signatures (expires_at)
    WHERE stage NOT IN ('signed', 'expired', 'failed');

CREATE INDEX signatures_signer_email_idx ON signatures (signer_email, created_at DESC);
